import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'currency_card.dart' show CurrencyCard;
import '../news_list/widgets/news_card.dart' show NewsCard;

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late Future<List<dynamic>> _dashboardFuture;
  late final AnimationController _fadeController;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      _fadeController.forward();
      return results;
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<List<dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<List<dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (!snapshot.hasData || snapshot.data!.isEmpty) {
            return const Center(child: Text('No data'));
          }

          final CurrencyPage currencyPage = snapshot.data![0] as CurrencyPage;
          final List<NewsModel> newsList = snapshot.data![1] as List<NewsModel>;

          return FadeTransition(
            opacity: _fadeController.view,
            child: ListView(
              padding: const EdgeInsets.symmetric(vertical: 8),
              children: [
                // Currency section
                Padding(
                  padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
                  child: Text(
                    loc.currencies,
                    style: context.fonts.regular16.copyWith(fontWeight: FontWeight.w700),
                  ),
                ),
                ...currencyPage.items.map((CurrencyModel currency) {
                  return Padding(
                    padding: const EdgeInsets.only(left: 22, right: 22, top: 8),
                    child: CurrencyCard(model: currency),
                  );
                }),
                // News section
                if (newsList.isNotEmpty) ...[
                  Padding(
                    padding: const EdgeInsets.fromLTRB(22, 24, 22, 8),
                    child: Text(
                      loc.news,
                      style: context.fonts.regular16.copyWith(fontWeight: FontWeight.w700),
                    ),
                  ),
                  ...newsList.map((NewsModel news) {
                    return Padding(
                      padding: const EdgeInsets.fromLTRB(22, 8, 22, 0),
                      child: NewsCard(model: news),
                    );
                  }),
                ],
              ],
            ),
          );
        },
      ),
    );
  }
}

